ull,"recipe_id":"730703aa-438f-416a-b775-c7eb1e4c5892","time_seconds":180},{"id":"7a3bdda5-f6ef-4033-8587-777a3ae80c9f","text":"同鍋加入牛油，炒香蒜蓉和蘑菇 2 至 3 分鐘。","step_no":4,"image_url":null,"recipe_id":"730703aa-438f-416a-b775-c7eb1e4c5892","time_seconds":210},{"id":"7fcaba43-6a7b-4c29-abdf-29e9c074d33a","text":"蘑菇切片，蒜頭切蓉，菠菜洗淨瀝乾。","step_no":2,"image_url":null,"recipe_id":"730703aa-438f-416a-b775-c7eb1e4c5892","time_seconds":150},{"id":"9dc9d231-adee-49fa-89ee-682058e75030","text":"平底鑊下橄欖油，中火把雞肉煎至熟透後盛起。","step_no":3,"image_url":null,"recipe_id":"730703aa-438f-416a-b775-c7eb1e4c5892","time_seconds":300},{"id":"a1e49e62-c864-40da-a279-0e6e37371e07","text":"加入菠菜炒至剛軟，再倒入忌廉和牛奶，小火煮至微稠。","step_no":5,"image_url":null,"recipe_id":"730703aa-438f-416a-b775-c7eb1e4c5892","time_seconds":180},{"id":"da49204d-5360-4407-98f5-79ec7817a8b3","text":"加入雞肉回鍋，試味後淋在熱飯上即可。","step_no":6,"image_url":null,"recipe_id":"730703aa-438f-416a-b775-c7eb1e4c5892","time_seconds":90}]}}'::jsonb p;
DO $cream$
DECLARE p jsonb; actual jsonb; item jsonb; affected int; shown_before jsonb;
BEGIN
 SELECT cream_patch.p INTO p FROM cream_patch;
 PERFORM id FROM public.recipes WHERE id='730703aa-438f-416a-b775-c7eb1e4c5892' FOR UPDATE;
 SELECT to_jsonb(times_shown) INTO shown_before FROM public.recipes WHERE id='730703aa-438f-416a-b775-c7eb1e4c5892';
 PERFORM id FROM public.recipe_ingredients WHERE recipe_id='730703aa-438f-416a-b775-c7eb1e4c5892' ORDER BY id FOR UPDATE;
 PERFORM id FROM public.recipe_steps WHERE recipe_id='730703aa-438f-416a-b775-c7eb1e4c5892' ORDER BY id FOR UPDATE;
 SELECT jsonb_build_object('recipe',(SELECT to_jsonb(r)-'updated_at'-'times_shown' FROM public.recipes r WHERE id='730703aa-438f-416a-b775-c7eb1e4c5892'),'ingredients',(SELECT jsonb_agg(to_jsonb(i) ORDER BY id) FROM public.recipe_ingredients i WHERE recipe_id='730703aa-438f-416a-b775-c7eb1e4c5892'),'steps',(SELECT jsonb_agg(to_jsonb(s) ORDER BY id) FROM public.recipe_steps s WHERE recipe_id='730703aa-438f-416a-b775-c7eb1e4c5892')) INTO actual;
 IF actual IS DISTINCT FROM p->'before' THEN RAISE EXCEPTION 'Cream reformulation precondition changed'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p->'after'->'ingredients') WHERE value->>'ingredient_id' IN ('92a6a27a-ad0b-4375-b166-935d7455c9ff','c8ab2483-73dd-488c-b2ca-75ef594b0136') LOOP
  UPDATE public.recipe_ingredients SET quantity=(item->>'quantity')::numeric WHERE id=(item->>'id')::uuid AND recipe_id='730703aa-438f-416a-b775-c7eb1e4c5892';
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected<>1 THEN RAISE EXCEPTION 'Cream ingredient identity changed'; END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p->'after'->'steps') WHERE (value->>'step_no')::int IN (1,6) LOOP
  UPDATE public.recipe_steps SET text=item->>'text' WHERE id=(item->>'id')::uuid AND recipe_id='730703aa-438f-416a-b775-c7eb1e4c5892';
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected<>1 THEN RAISE EXCEPTION 'Cream step identity changed'; END IF;
 END LOOP;
 UPDATE public.recipes SET calories_per_serving=(p->'after'->'recipe'->>'calories_per_serving')::numeric,
 protein_g=(p->'after'->'recipe'->>'protein_g')::numeric,carbs_g=(p->'after'->'recipe'->>'carbs_g')::numeric,
 fat_g=(p->'after'->'recipe'->>'fat_g')::numeric,source_data=p->'after'->'recipe'->'source_data' WHERE id='730703aa-438f-416a-b775-c7eb1e4c5892';
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF affected<>1 THEN RAISE EXCEPTION 'Cream recipe identity changed'; END IF;
 SELECT jsonb_build_object('recipe',(SELECT to_jsonb(r)-'updated_at'-'times_shown' FROM public.recipes r WHERE id='730703aa-438f-416a-b775-c7eb1e4c5892'),'ingredients',(SELECT jsonb_agg(to_jsonb(i) ORDER BY id) FROM public.recipe_ingredients i WHERE recipe_id='730703aa-438f-416a-b775-c7eb1e4c5892'),'steps',(SELECT jsonb_agg(to_jsonb(s) ORDER BY id) FROM public.recipe_steps s WHERE recipe_id='730703aa-438f-416a-b775-c7eb1e4c5892')) INTO actual;
 IF actual IS DISTINCT FROM p->'after' OR (SELECT to_jsonb(times_shown) FROM public.recipes WHERE id='730703aa-438f-416a-b775-c7eb1e4c5892') IS DISTINCT FROM shown_before THEN RAISE EXCEPTION 'Cream final protected state changed'; END IF;
END $cream$;
COMMIT;
